if (resp_ext) {
	if (resp_ext->ngroups > NGROUPS_MAX) {
		pr_err("ngroups(%u) from login response exceeds max groups(%d)\n", ...);
		goto err_free;
	}
	user->sgid = kmemdup(resp_ext->____payload,
			     resp_ext->ngroups * sizeof(gid_t),
			     GFP_KERNEL);
	if (!user->sgid)
		goto err_free;
	user->ngroups = resp_ext->ngroups;

